import{_ as i,a0 as r,w as m,s as l,ao as p,I as o,x as t,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"保護你的文件，請在 Linux 中更改 Umask 值 | LCTT x X-CMD","titleTemplate":false,"description":"保護你的文件，請在 Linux 中更改 Umask 值 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保護你的文件，請在 Linux 中更改 Umask 值 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保護你的文件，請在 Linux 中更改 Umask 值 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to Change Umask Value Permanently in Linux","title":"保護你的文件，請在 Linux 中更改 Umask 值","tag":"201405","desc":""},"relativePath":"201405/How to Change Umask Value Permanently in Linux.md","filePath":"[post].md"}'),u={name:"201405/How to Change Umask Value Permanently in Linux.md"};function x(d,n,k,L,g,f){const e=r("Link");return m(),l("div",null,[n[11]||(n[11]=p(`<h1 id="保護你的文件-請在-linux-中更改-umask-值" tabindex="-1">保護你的文件，請在 Linux 中更改 Umask 值 <a class="header-anchor" href="#保護你的文件-請在-linux-中更改-umask-值" aria-label="Permalink to “保護你的文件，請在 Linux 中更改 Umask 值”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Change-Umask-Value-Permanently-in-Linux-435026-2.jpg" alt=""></p><p><strong>這篇教程教將指導 Linux 用户如何永久性地更改其系統的 Umask 值。特別建議全新安裝的用户學習（想知道為什麼的話，請移步下文）</strong></p><p>Umask 是什麼？解釋下，UMASK 代表用户掩碼或用户文件創建掩碼，它用於新創建的文件和文件夾，是其默認權限的基礎。</p><p>上面的意思可以解釋成任何基於 Linux 的操作系統為新建文件(包括文件夾)添加默認權限的規則。出於教育目的，下面列出了一些可以用來設置文件權限的八進制值<strong>掩碼</strong>：</p><pre><code>0 – 讀, 寫, 可執行 (rwx)
1 – 讀和寫 (rw-)
2 – 讀和可執行 (r-x)
3 – 只讀 (r--)
4 – 寫和可執行 (-wx)
5 – 只寫 (-w-)
6 – 僅可執行 (--x)
7 – 沒有權限 (---)
</code></pre><p>在幾乎所有的 Linux 發行版本中默認 Umask 值是 0022(或022)，可以在終端模擬程序中輸入 umask 命令來查看。也可以運行 “umask 八進制值掩碼” 命令（例如 umask 027）來臨時改變這個值。</p><p>你也許知道，新創建的文件的默認權限設置原本應該是 0666，文件夾的是 0777。應用上面所説的 umask 值後就得到 644 和 755 權限。</p><p>許多意見認為 022 掩碼會帶來隱私問題，也就是説您所創建的文件對其他用户來説是可隨意查看的，一想到這就感到不太爽！</p><p>言歸正傳，用户可以按他們所願來修改默認的 Umask 值，當然首先要保證修改的值合法。要修改默認值，<strong>請在您的 shell 配置文件中或者 /etc/profile 文件中寫入一個新的 Umask 值</strong>。</p><p>好了，這就大功告成了！從現在開始，在你的 Linux 系統上新創建的文件或文件夾都會有準確設置的權限。但請注意已經存在的文件或文件夾的權限並不會因為上面的操作而改變。</p><p>如果您使用的是命令列，可以在任意目錄下運行 ls -lah 命令，就可以看到當前的文件權限。另外，新手也可以很容易地查看到文件權限，在基於 GNOME 桌面的環境中，通過右擊文件，選擇屬性 -&gt; 權限選項卡。</p><p>如果你在閲讀這篇教程時遇到任何問題，不要猶豫，請留下您的評論。</p><hr>`,14)),o("p",null,[n[1]||(n[1]=t("via: ",-1)),a(e,{href:"http://news.softpedia.com/news/How-to-Change-Umask-Value-Permanently-in-Linux-435026.shtml"},{default:s(()=>[...n[0]||(n[0]=[t("http://news.softpedia.com/news/How-to-Change-Umask-Value-Permanently-in-Linux-435026.shtml",-1)])]),_:1})]),o("p",null,[n[4]||(n[4]=t("譯者：",-1)),a(e,{href:"https://github.com/runningwater"},{default:s(()=>[...n[2]||(n[2]=[t("runningwater",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),a(e,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[n[8]||(n[8]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),a(e,{href:"http://linux.cn/"},{default:s(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const U=i(u,[["render",x]]);export{w as __pageData,U as default};
